// ── ADMIN NOTIFICATIONS ───────────────────────────────────────────────────
function AdminNotifications({ db }) {
  const [alerts, setAlerts] = useState([]);
  useEffect(() => {
    const q = query(collection(db, 'admin_notifications'), orderBy('timestamp', 'desc'));
    const unsub = onSnapshot(q, snap => setAlerts(snap.docs.map(d => ({ id: d.id, ...d.data() }))));
    return () => unsub();
  }, [db]);
  const clear = async () => {
    if (!window.confirm("Clear all security notifications?")) return;
    const snap = await getDocs(collection(db, 'admin_notifications'));
    await Promise.all(snap.docs.map(d => deleteDoc(d.ref)));
  };
  if (!alerts.length) return null;
  return (
    <div style={{ background: '#FFF3E0', border: '1px solid #FFB74D', borderRadius: 12, padding: 15, marginBottom: 20 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
        <h4 style={{ margin: 0, color: '#E65100', display: 'flex', alignItems: 'center', gap: 8 }}>
          <i className="fas fa-bell"></i> Security Alerts
          <span style={{ background: '#E65100', color: 'white', borderRadius: 10, padding: '1px 8px', fontSize: 11 }}>{alerts.length}</span>
        </h4>
        <button onClick={clear} style={{ background: 'none', border: '1px solid #E65100', color: '#E65100', borderRadius: 6, padding: '5px 10px', cursor: 'pointer', fontSize: 12, display: 'inline-flex', alignItems: 'center', gap: 5 }}>
          <i className="fas fa-trash"></i> Clear All
        </button>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 200, overflowY: 'auto' }}>
        {alerts.map(a => (
          <div key={a.id} style={{ fontSize: 13, padding: '8px 10px', background: 'white', borderRadius: 6, display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: '3px solid #FF5722' }}>
            <span>{a.message}</span>
            <span style={{ color: '#999', fontSize: 11, minWidth: 60, textAlign: 'right', flexShrink: 0 }}>{new Date(a.timestamp).toLocaleTimeString()}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

